CREATE TABLE IF NOT EXISTS "bpm_approval_scheme" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "code" varchar(64) NOT NULL,
    "name" varchar(128) NOT NULL,
    "module_code" varchar(64) NOT NULL,
    "biz_type" varchar(64) NOT NULL,
    "scene_id" bigint DEFAULT NULL,
    "remark" varchar(255) DEFAULT NULL,
    "active_version_id" bigint DEFAULT NULL,
    "latest_version_id" bigint DEFAULT NULL,
    "owner_user_id" bigint NOT NULL DEFAULT 0,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT '审批方案';

CREATE TABLE IF NOT EXISTS "bpm_approval_scheme_version" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "scheme_id" bigint NOT NULL,
    "version_no" int NOT NULL,
    "status" tinyint NOT NULL,
    "source_version_id" bigint DEFAULT NULL,
    "source_type" varchar(32) NOT NULL DEFAULT 'CREATE',
    "design_json" clob NOT NULL,
    "change_summary" varchar(255) DEFAULT NULL,
    "published_by" varchar(64) DEFAULT NULL,
    "published_time" timestamp DEFAULT NULL,
    "notify_json" clob DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT '审批方案版本';

CREATE TABLE IF NOT EXISTS "bpm_approval_rule" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "scheme_version_id" bigint NOT NULL,
    "rule_name" varchar(128) NOT NULL,
    "rule_type" varchar(32) NOT NULL,
    "priority" int NOT NULL DEFAULT 1,
    "is_default" bit NOT NULL DEFAULT FALSE,
    "condition_json" clob DEFAULT NULL,
    "process_json" clob DEFAULT NULL,
    "enabled" bit NOT NULL DEFAULT TRUE,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT '审批规则';

CREATE TABLE IF NOT EXISTS "bpm_approval_scene" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "scene_code" varchar(128) NOT NULL,
    "name" varchar(128) NOT NULL,
    "module_code" varchar(64) NOT NULL,
    "biz_type" varchar(64) NOT NULL,
    "action_code" varchar(64) NOT NULL,
    "active_scheme_id" bigint DEFAULT NULL,
    "status" tinyint NOT NULL DEFAULT 1,
    "remark" varchar(255) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT '审批场景';

CREATE TABLE IF NOT EXISTS "bpm_approval_instance_snapshot" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "scene_code" varchar(128) NOT NULL,
    "biz_id" varchar(64) NOT NULL,
    "scheme_id" bigint NOT NULL,
    "scheme_version_id" bigint NOT NULL,
    "rule_id" bigint NOT NULL,
    "process_instance_id" varchar(64) DEFAULT NULL,
    "process_definition_key" varchar(128) DEFAULT NULL,
    "context_json" clob DEFAULT NULL,
    "process_json" clob DEFAULT NULL,
    "notify_json" clob DEFAULT NULL,
    "status" tinyint NOT NULL DEFAULT 1,
    "result_reason" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT '审批运行时快照';
